crds.yaml:
apiVersion: leloir.dev/v1alpha1
kind: TenantBudget
metadata: { name: team-alpha-budget, namespace: team-alpha }
spec:
  monthly: { maxUSD: 50.0, alertAtPercent: 80, hardLimitAction: reject }
  perInvestigation: { maxUSD: 5.0, maxTokens: 100000, maxToolCalls: 50 }
  a2a: { maxInvocationDepth: 5, maxFanOutPerAgent: 3 }

apiVersion: leloir.dev/v1alpha1
kind: NotificationChannel
metadata: { name: teams-sre, namespace: team-alpha }
spec:
  type: teams
  teams: { webhookURLSecretRef: { name: teams-webhook-secret, key: url } }
  notification: { includeRootCause: true, includeCost: true, onOutcomes: [success, error] }
